"""Regenerate render.yaml and .env.example from the settings table in config.py:  python make_render.py"""
import os

import config as C

HERE = os.path.dirname(os.path.abspath(__file__))
OVERRIDES = {"STATE_FILE": "/var/data/state.json"}

lines = [
    "# Render Blueprint: New > Blueprint > pick this repo. Generated by make_render.py from config.py.",
    "services:",
    "  - type: worker                 # background worker: no port, never sleeps",
    "    name: kronos-limit-bot",
    "    runtime: python",
    "    region: frankfurt",
    "    plan: standard               # 2 GB RAM / 1 CPU; use pro for a big universe or Kronos-base",
    "    buildCommand: bash build.sh",
    "    startCommand: python bot.py",
    "    disk:                        # keeps state.json (open positions!) across deploys/restarts",
    "      name: bot-state",
    "      mountPath: /var/data",
    "      sizeGB: 1",
    "    envVars:",
    "      - key: PYTHON_VERSION",
    "        value: 3.11.11",
    "      - key: HF_HOME",
    "        value: /opt/render/project/src/.hf_cache",
]
for name, default, typ, grp, help_ in C.VARS:
    if name in C.SECRETS or name == "CONFIRM_LIVE":
        lines += [f"      - key: {name}            # {help_}", "        sync: false"]
        continue
    v = OVERRIDES.get(name, default)
    v = str(v).lower() if typ is bool else v
    lines += [f"      - key: {name}", f'        value: "{v}"']

with open(os.path.join(HERE, "render.yaml"), "w") as fh:
    fh.write("\n".join(lines) + "\n")
with open(os.path.join(HERE, ".env.example"), "w") as fh:
    fh.write(C.env_example())
print("wrote render.yaml and .env.example")
